import{_ as t,o,c as a,a4 as n}from"./chunks/framework.CKd2nDfM.js";const u=JSON.parse(`{"title":"Design language","description":"Material Plus implements the Material Design specification rather than wrapping somebody's implementation of it. That one decision is where almost everything…","frontmatter":{"title":"Design language","order":0},"headers":[],"relativePath":"design/design-language.md","filePath":"en/design/design-language.md","lastUpdated":1788501759000}`),s={name:"design/design-language.md"};function i(r,e,d,c,h,l){return o(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="design-language" tabindex="-1">Design language <a class="header-anchor" href="#design-language" aria-label="Permalink to &quot;Design language&quot;">​</a></h1><p class="mp-lede">Material Plus implements the Material Design specification rather than wrapping somebody&#39;s implementation of it. That one decision is where almost everything on this page comes from — the words the props use, the values the tokens hold, and the four places the library knowingly goes past what the spec says.</p><p>The rule is: <strong>where the spec has a word, use the spec&#39;s word.</strong> A colour role is <code>primary</code> or <code>on-surface-variant</code>, a corner is <code>extra-small</code>, a type role is <code>body-large</code>, a density step is <code>-1</code>. They are not Material UI&#39;s words: MUI&#39;s palette is <code>main</code>/<code>light</code>/<code>dark</code>/<code>contrastText</code>, which is a different and earlier colour model, and borrowing those names would describe a system this library does not implement.</p><h2 id="the-surface" tabindex="-1">The surface <a class="header-anchor" href="#the-surface" aria-label="Permalink to &quot;The surface&quot;">​</a></h2><p>Everything here is drawn on one of Material&#39;s neutral surface roles, and never on an accent.</p><p>That sounds like a small thing and it decides the look of the whole library. A container holds <strong>somebody else&#39;s</strong> content, and that content arrives with its own colours — body text, links, fields, buttons. On an accent fill, every one of them would need an on-accent treatment of its own. So a container&#39;s <code>variant</code> ladder runs up the neutral roles instead, and the loudest it goes is <code>surface-container-highest</code>, which is the specification&#39;s own filled card:</p><table tabindex="0"><thead><tr><th><code>variant</code></th><th>What a container paints</th></tr></thead><tbody><tr><td><code>filled</code></td><td><code>surface-container-highest</code></td></tr><tr><td><code>tonal</code></td><td><code>surface-container</code></td></tr><tr><td><code>elevated</code></td><td><code>surface-container-low</code>, under a level-1 shadow</td></tr><tr><td><code>outlined</code></td><td>nothing, plus a hairline in <code>outline-variant</code></td></tr><tr><td><code>text</code></td><td>nothing at all</td></tr></tbody></table><p>The same five words mean something different on a component that <strong>is</strong> the thing being coloured — a button, a chip, a badge — where <code>filled</code> is the accent under its own ink. That is not an inconsistency, it is the distinction: <code>filled</code> is a statement about emphasis, and what it paints depends on whether the component is the subject or the stage.</p><h2 id="colour-is-a-role-never-a-value" tabindex="-1">Colour is a role, never a value <a class="header-anchor" href="#colour-is-a-role-never-a-value" aria-label="Permalink to &quot;Colour is a role, never a value&quot;">​</a></h2><p>The scheme is generated from <strong>one source colour</strong>, the way Material generates one. Set <code>--mp-source-color</code> and every role follows. No provider, no theme object, no re-render — it is CSS, so a section of a page can differ from the rest of it without either knowing.</p><p>That is why <code>color</code> takes a family rather than a colour, and why there are four of them: <code>primary</code>, <code>secondary</code>, <code>tertiary</code>, <code>error</code>. MD3&#39;s colour system has no <code>success</code>, <code>info</code> or <code>warning</code>, and offering them would promise roles the token sheet has no way to derive. An alert that needs green sets a token; it does not get a fifth family that the rest of the library cannot honour.</p><p>See <a href="./color">Colour</a> for the roles and how to move one.</p><h2 id="size-is-the-one-place-this-goes-past-the-spec" tabindex="-1">Size is the one place this goes past the spec <a class="header-anchor" href="#size-is-the-one-place-this-goes-past-the-spec" aria-label="Permalink to &quot;Size is the one place this goes past the spec&quot;">​</a></h2><p>Material defines a single size per component. A text field is 56dp, full stop — because it is describing a design system for whole products, where one height per control is the point.</p><p>A component library gets used in places a design system does not plan for: a filter bar, a table&#39;s inline editor, a dense settings page, a marketing hero. Those need a ladder, and a consumer who cannot get one from the library builds it out of <code>!important</code>.</p><p>So there are five rungs and <strong><code>md</code> is the spec&#39;s</strong>:</p><table tabindex="0"><thead><tr><th><code>size</code></th><th>Control height</th></tr></thead><tbody><tr><td><code>xs</code></td><td>32px</td></tr><tr><td><code>sm</code></td><td>40px</td></tr><tr><td><code>md</code></td><td>56px — MD3&#39;s own</td></tr><tr><td><code>lg</code></td><td>64px</td></tr><tr><td><code>xl</code></td><td>72px</td></tr></tbody></table><p>The ladder is centred rather than starting at the specification&#39;s value, and that is the whole trick: <code>md</code> is what you get by saying nothing, so nobody has to know the scale exists to be given the Material size. <code>xs</code> and <code>xl</code> sit at the edges of usable rather than merely smaller and larger — below <code>xs</code> a control stops meeting a 24px touch target — and there is no sixth step, because a ladder long enough to need one is a sign the caller wants a custom control.</p><h2 id="density-is-a-second-axis-not-a-longer-ladder" tabindex="-1">Density is a second axis, not a longer ladder <a class="header-anchor" href="#density-is-a-second-axis-not-a-longer-ladder" aria-label="Permalink to &quot;Density is a second axis, not a longer ladder&quot;">​</a></h2><p><code>size</code> picks which control this is. <a href="./prop-conventions#density"><code>density</code></a> takes room out of the one that was picked, on Material&#39;s own scale of <code>0</code> to <code>-3</code> at four pixels a step, and it takes it out of the <strong>spacing only</strong> — the type scale does not move.</p><p>The two cannot be collapsed into one. <code>size=&quot;sm&quot;</code> on a list is a small list; <code>density={-2}</code> is a normal list with more of it on the screen. A dense screen wants the second: more rows, at the size they could already read. Shrinking the text to fit more of them makes them harder to read at exactly the moment there are more of them.</p><p>Only the components that hold things take it, and every step lands on a height the size ladder already has a name for — so a dense list and the button beside it still line up.</p><h2 id="height-moves-the-tone-with-it" tabindex="-1">Height moves the tone with it <a class="header-anchor" href="#height-moves-the-tone-with-it" aria-label="Permalink to &quot;Height moves the tone with it&quot;">​</a></h2><p>An <a href="./prop-conventions#elevation"><code>elevation</code></a> is a surface role <strong>and</strong> a shadow, never one without the other. MD3 does not treat height as a free axis: an elevated surface is <code>surface-container-low</code> under a level-1 shadow, and the two are one decision. A prop that only cast a shadow would raise a <code>filled</code> box into a surface the specification has no name for.</p><p>Shadows are the specification&#39;s own two-shadow recipe — a tight key shadow plus a wider ambient one — rather than one blurred box. The pair is what makes a raised surface read as lit from above instead of as a sticker with a halo.</p><h2 id="a-corner-says-what-kind-of-object-something-is" tabindex="-1">A corner says what kind of object something is <a class="header-anchor" href="#a-corner-says-what-kind-of-object-something-is" aria-label="Permalink to &quot;A corner says what kind of object something is&quot;">​</a></h2><p>The radius is not a size to taste. In Material it is a statement about what a thing <strong>is</strong>, so it does not move with <code>size</code>:</p><ul><li><code>extra-small</code>, 4px — a row in a list, an option in a menu.</li><li><code>medium</code>, 12px — a sheet. A box and a card are <code>corner-medium</code> at every rung.</li><li><code>extra-large</code>, 28px — a dialog. A sheet that has taken the page is allowed to look like an object rather than like a panel.</li><li><code>full</code> — a pill. A button, a chip, a track.</li></ul><h2 id="states-are-a-layer-not-a-second-colour" tabindex="-1">States are a layer, not a second colour <a class="header-anchor" href="#states-are-a-layer-not-a-second-colour" aria-label="Permalink to &quot;States are a layer, not a second colour&quot;">​</a></h2><p>Hover, focus and press are a translucent wash of the <strong>content</strong> colour over the container: 8% hovered, 10% focused or pressed. One rule covers a filled button, an outlined one and a bare text one, and none of them names a second background.</p><p>It has to be a layer rather than a <code>hover:bg-…</code> because a background can only be replaced. Replacing one is what makes a text button&#39;s hover state opaque and an outlined button&#39;s hover state cover its own border. A layer composites, so whatever was underneath — a fill, a hairline, nothing — is still there under the wash.</p><h2 id="motion-is-a-token-and-it-has-a-direction" tabindex="-1">Motion is a token, and it has a direction <a class="header-anchor" href="#motion-is-a-token-and-it-has-a-direction" aria-label="Permalink to &quot;Motion is a token, and it has a direction&quot;">​</a></h2><p>Every duration and curve is a custom property, so a page that wants everything a little slower sets one value. <code>MPEasing</code> takes the specification&#39;s names and no arbitrary <code>cubic-bezier()</code>, for the same reason <code>color</code> takes a family: a curve written into one component&#39;s props is a curve the theme cannot reach.</p><p>The pairs are how Material describes a transition rather than four interchangeable options. Something <strong>arriving</strong> decelerates into place; something <strong>leaving</strong> accelerates away. That asymmetry is in the defaults, so an exit is quicker than an entrance without anybody having to know the numbers.</p><p><code>prefers-reduced-motion</code> is honoured by the components and by the stylesheet, everywhere, with no prop to set.</p><h2 id="it-coexists" tabindex="-1">It coexists <a class="header-anchor" href="#it-coexists" aria-label="Permalink to &quot;It coexists&quot;">​</a></h2><p>Nothing here is page-level. No reset, no provider, no global styling — and the components read the <code>--md-sys-color-*</code> tokens your page already has if they are there, so a project already running Material keeps its own setup.</p><p>This is the reason for a handful of decisions that look odd on their own. Every control writes <code>box-sizing</code> explicitly, because with no page reset an outlined box&#39;s hairline would land outside its padding and come out two pixels wider than a filled one beside it. <code>&lt;ul role=&quot;list&quot;&gt;</code> is said out loud, because a host reset may take the bullets off and Safari takes the list semantics with them. A table&#39;s padding is inline, because <code>.prose td</code> and <code>.vp-doc td</code> style cells by tag name at a specificity a utility cannot outrank.</p><p>A component library that assumed it owned the page would not need any of that. This one does not assume it.</p><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to &quot;Next&quot;">​</a></h2><ul><li><a href="./color">Colour</a> — the roles, and how to theme them.</li><li><a href="./prop-conventions">Prop conventions</a> — the shared vocabulary, axis by axis.</li><li><a href="./breakpoints">Breakpoints</a> — the window size classes everything reflows at.</li></ul>',41)])])}const g=t(s,[["render",i]]);export{u as __pageData,g as default};
